// ----- Chart Data -----
const chartData = ref<RevenueData[]>([])
const totalEarningsUSD = ref(0)
const totalEarningsBTC = ref(0)
const averagePhs = ref(0)
// NUEVA VARIABLE
const averageBtcPrice = ref(0)
const btcPriceNow = ref(0)


// add a ref to the ApexChart component
