  },

  title: {
    text: 'USDT/p'
  }
},




    yaxis: {
      title: { text: 'Fecha' },
      min: 0,
      max: maxRevenue,
      
      labels: {
        formatter: (val: number) =>
          `${val.toLocaleString(undefined, { maximumFractionDigits: 0 })}`
      }
    },

